func lessonsThatFit(_ minutes: [Int], budget: Int) -> Int {
    var used = 0
    var count = 0
    for lesson in minutes {
        if used + lesson > budget { break }
        used += lesson
        count += 1
    }
    return count
}
assert(lessonsThatFit([20, 30, 15], budget: 50) == 2)
assert(lessonsThatFit([60, 10], budget: 50) == 0)
assert(lessonsThatFit([25, 25], budget: 50) == 2)
assert(lessonsThatFit([], budget: 50) == 0)

Результат — число, поэтому место результата — счётчик, а не массив. Нужен второй аккумулятор used: решение по уроку зависит от уже потраченных минут. break завершает проход на первом уроке, который не влезает: [60, 10] даёт 0, хотя 10 поместилось бы, — так требует «по порядку». Точное равенство влезает: 25 + 25 = 50.

